  # Renders an official Heroicons v2 path. Decorative by default (aria-hidden) --
  # interactive elements that are icon-only must supply their own aria-label.
  #
  #   heroicon(:home)
  #   heroicon(:trash, class: "size-4 text-rose-700")
  #   heroicon(:check_circle, variant: :solid, class: "size-5 text-emerald-700")
  def heroicon(name, variant: :outline, class: "size-5", **options)
    paths = HEROICON_PATHS.fetch(variant).fetch(name.to_sym) do
      raise ArgumentError, "Unknown heroicon #{variant}/#{name}"
    end
    path_attrs = variant == :outline ? { stroke_linecap: "round", stroke_linejoin: "round" } : { fill_rule: "evenodd", clip_rule: "evenodd" }

    content_tag(:svg, safe_join(paths.map { |d| tag.path(d:, **path_attrs) }),
      viewBox: "0 0 24 24",
      fill: variant == :outline ? "none" : "currentColor",
      stroke: variant == :outline ? "currentColor" : nil,
      "stroke-width": variant == :outline ? "1.5" : nil,
      class:, aria: { hidden: true }, **options)
  end
end
